/*
Core observation:
A rigid polyline can be moved through a point-hole into y < 0 iff there exists
some point on the polyline such that, when that point is placed at the hole,
the whole polyline lies in some closed half-plane bounded by a line through that point.

For a polyline, it is enough to check each vertex as the hole-contact point.
At a chosen vertex v, all incident chain directions from v to every other vertex
must fit inside some angle of at most 180 degrees. Equivalently, the set of vectors
from v to all other vertices must lie in a closed half-plane through the origin.

This is true iff there exists a direction n such that dot(n, p_i - v) >= 0 for all i,
which can be checked by angular span: all vectors fit in some semicircle.
*/

static int cmp_double(const void *a, const void *b) {
    double x = *(const double *)a;
    double y = *(const double *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int fits_semicircle(Point *p, int n, int pivot) {
    if (n <= 2) return 1;

    double *ang = (double *)malloc((n - 1) * sizeof(double));
    int m = 0;

    for (int i = 0; i < n; i++) {
        if (i == pivot) continue;
        Point v = sub(p[i], p[pivot]);
        if (fabs(v.x) < EPS && fabs(v.y) < EPS) continue;
        ang[m++] = atan2(v.y, v.x);
    }

    if (m <= 1) {
        free(ang);
        return 1;
    }

    qsort(ang, m, sizeof(double), cmp_double);

    double *ext = (double *)malloc(2 * m * sizeof(double));
    for (int i = 0; i < m; i++) {
        ext[i] = ang[i];
        ext[i + m] = ang[i] + 2.0 * M_PI;
    }

    int j = 0;
    for (int i = 0; i < m; i++) {
        if (j < i) j = i;
        while (j + 1 < i + m && ext[j + 1] - ext[i] < M_PI - EPS) j++;
        /* points from i..j fit in an open semicircle; with boundary allowed,
           we may also include angle exactly pi */
        while (j + 1 < i + m && ext[j + 1] - ext[i] <= M_PI + EPS) j++;

        if (j - i + 1 >= m) {
            free(ang);
            free(ext);
            return 1;
        }
    }

    free(ang);
    free(ext);
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point *p = (Point *)malloc(n * sizeof(Point));
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &p[i].x, &p[i].y);
    }

    int ok = 0;
    for (int i = 0; i < n; i++) {
        if (fits_semicircle(p, n, i)) {
            ok = 1;
            break;
        }
    }

    printf(ok ? "YES\n" : "NO\n");

    free(p);
    return 0;
}

