def point_in_convex_polygon(pts, x, y):
    n = len(pts)
    sign = None
    for i in range(n):
        x1, y1 = pts[i]
        x2, y2 = pts[(i + 1) % n]
        c = cross(x2 - x1, y2 - y1, x - x1, y - y1)
