public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = sc.nextDouble();
            y[i] = sc.nextDouble();
        }

        // Convert each vertex to a constraint on angle θ:
        // For each point, we need: -x*sinθ + y*cosθ <= 0
        // That means: (y, -x) dot (cosθ, sinθ) <= 0
        // Equivalent to angle condition: angle of (cosθ, sinθ) in [α, α+π] mod 2π
        List<double[]> intervals = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            double a = y[i];
            double b = -x[i];
            if (a == 0 && b == 0) continue; // point at origin imposes no restriction
            double ang = Math.atan2(b, a); // angle of normal vector
            double start = ang;
            double end = ang + Math.PI;
            // Normalize to [0, 2π)
            start = normalize(start);
            end = normalize(end);
            intervals.add(new double[]{start, end});
        }

        if (intervals.isEmpty()) {
            System.out.println("Yes");
            return;
        }

        // Merge intervals on a circle
        // We'll duplicate intervals shifted by 2π to handle wrap-around
        List<double[]> doubled = new ArrayList<>();
        for (double[] iv : intervals) {
            doubled.add(new double[]{iv[0], iv[1]});
            doubled.add(new double[]{iv[0] + 2 * Math.PI, iv[1] + 2 * Math.PI});
        }

        doubled.sort((a, b) -> Double.compare(a[0], b[0]));

        double curEnd = doubled.get(0)[0];
        for (double[] iv : doubled) {
            if (iv[0] > curEnd) {
                // gap found — possible angle exists
                System.out.println("Yes");
                return;
            }
            curEnd = Math.max(curEnd, iv[1]);
            if (curEnd >= 2 * Math.PI) break;
        }

        System.out.println("No");
    }

    static double normalize(double a) {
        while (a < 0) a += 2 * Math.PI;
        while (a >= 2 * Math.PI) a -= 2 * Math.PI;
        return a;
    }
}

