A standard interpretation of this classic task is:

Given a simple polyline with n vertices (in order), determine whether it can be moved
(by rigid motions: translation + rotation, no deformation) through a point-hole at (0,0)
so that eventually the whole polyline lies in the half-plane y < 0.

Key geometric fact:
A rigid polyline can pass through a point-hole into a half-plane iff there exists a line
through some point of the polyline such that the orthogonal projection of the whole polyline
onto the line's normal has width not exceeding 0 while "threading" through the hole.
For a polyline, this reduces to whether there exists a direction such that the polyline is
monotone with respect to that direction. Equivalently, all edge direction angles lie within
some interval of length <= 180 degrees.

This is the same as asking whether the set of edge direction angles can be covered by a semicircle.
If yes => answer YES, else NO.

Input assumption used here:
n
x1 y1
x2 y2
...
xn yn

Output:
YES or NO

If your original judge uses another exact format, only parsing may need adjustment.
*/

public class Main {
    static final double PI = Math.PI;
    static final double EPS = 1e-12;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        if (!fs.hasNext()) return;
        n = fs.nextInt();

        double[] x = new double[n];
        double[] y = new double[n];
        for (int i = 0; i < n; i++) {
            x[i] = fs.nextDouble();
            y[i] = fs.nextDouble();
        }

        if (n <= 2) {
            System.out.println("YES");
            return;
        }

        ArrayList<Double> ang = new ArrayList<>();
        for (int i = 0; i + 1 < n; i++) {
            double dx = x[i + 1] - x[i];
            double dy = y[i + 1] - y[i];
            if (Math.abs(dx) < EPS && Math.abs(dy) < EPS) continue;
            double a = Math.atan2(dy, dx);
            if (a < 0) a += 2 * PI;
            ang.add(a);
        }

        int m = ang.size();
        if (m <= 1) {
            System.out.println("YES");
            return;
        }

        Collections.sort(ang);

        double[] arr = new double[2 * m];
        for (int i = 0; i < m; i++) {
            arr[i] = ang.get(i);
            arr[i + m] = ang.get(i) + 2 * PI;
        }

        // Check if all directions fit inside some interval of length PI.
        boolean ok = false;
        int r = 0;
        for (int l = 0; l < m; l++) {
            if (r < l) r = l;
            while (r + 1 < l + m && arr[r + 1] - arr[l] < PI + EPS) r++;
            if (r - l + 1 >= m) {
                ok = true;
                break;
            }
        }

        System.out.println(ok ? "YES" : "NO");
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1) {
                if (!Character.isWhitespace(c)) {
                    ptr--;
                    return true;
                }
            }
            return false;
        }

        String next() throws IOException {
            int c;
            while ((c = read()) != -1 && Character.isWhitespace(c)) {}
            if (c == -1) return null;
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (c != -1 && !Character.isWhitespace(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

