using ll = long long;

struct Point {
    ll x, y;
    Point() : x(0), y(0) {}
    Point(ll _x, ll _y) : x(_x), y(_y) {}
    Point operator-(const Point &p) const { return Point(x - p.x, y - p.y); }
    ll cross(const Point &p) const { return x * p.y - y * p.x; }
    ll cross(const Point &a, const Point &b) const { return (a - *this).cross(b - *this); }
};

bool onSegment(Point p, Point a, Point b) {
    if (p.cross(a, b) != 0) return false;
    ll minx = min(a.x, b.x), maxx = max(a.x, b.x);
    ll miny = min(a.y, b.y), maxy = max(a.y, b.y);
    return p.x >= minx && p.x <= maxx && p.y >= miny && p.y <= maxy;
}

bool pointInConvexPolygon(const vector<Point> &poly, Point p) {
    int n = poly.size();
    if (n < 3) return false;
    if (p.cross(poly[0], poly[1]) > 0 || p.cross(poly[0], poly[n-1]) < 0) return false;
    int lo = 1, hi = n - 1;
    while (lo < hi) {
        int mid = (lo + hi + 1) / 2;
        if (p.cross(poly[0], poly[mid]) >= 0) lo = mid;
        else hi = mid - 1;
    }
    if (lo == 1 || lo == n - 1) {
        for (int i = 0; i < n; i++) {
            int j = (i+1)%n;
            if (onSegment(p, poly[i], poly[j])) return true;
        }
        return false;
    }
    return p.cross(poly[lo], poly[lo+1]) <= 0;
}

vector<Point> convexHull(vector<Point> pts) {
    int n = pts.size();
    if (n <= 1) return pts;
    sort(pts.begin(), pts.end(), [](const Point &a, const Point &b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    vector<Point> hull;
    for (int phase = 0; phase < 2; phase++) {
        int start = hull.size();
        for (auto &p : pts) {
            while (hull.size() >= start + 2 && hull.back().cross(hull[hull.size()-2], p) <= 0)
                hull.pop_back();
            hull.push_back(p);
        }
        hull.pop_back();
        reverse(pts.begin(), pts.end());
    }
    return hull;
}

